Given an array arr[] and an integer k, the task is to find the count of subarrays such that each subarray has exactly k distinct elements.Examples:Input: arr[] = [1, 2, 2, 3], k = 2 Output: 4 Explanation: Subarrays with exactly 2 distinct elements are: [1, 2], [1, 2, 2] and [2, 3].Input: arr[] = [3, 1, 2, 2, 3], k = 3 Output: 4Explanation: Subarrays with exactly 3 distinct elements are: [3, 1, 2], [3, 1, 2, 2], [3, 1, 2, 2, 3] and [1, 2, 2, 3].Input: arr[] = [1, 1, 1, 1], k = 2Output: 0Explanation: There is no subarray having exactly 2 distinct integers.Try It YourselfTable of Content[Naive Approach] Exploring all subarrays - O(n^2) Time and O(n) Space[Expected Approach] Using Sliding Window Technique - O(n) Time and O(n) Space[Naive Approach] Exploring all subarrays - O(n^2) Time and O(n) SpaceThe idea is to iterate over all possible subarrays while keeping the count of distinct integers using a hash set. For every subarray, check if the size of hash set is equal to k. If the size of hash set equals k, increment the result by 1. After iterating over all subarrays, return the result. 
            C++

    // C++ Code to count the subarrays having exactly
// k distinct elements by exploring all subarrays

#include <iostream>
#include <unordered_set>
#include <vector>
using namespace std;

int exactlyK(vector<int> &arr, int k) {
    int n = arr.size();
    int res = 0;

    // Iterate over all subarrays arr[i...j]
    for (int i = 0; i < n; i++) {

        // hash set to count distinct elements
        unordered_set<int> st;

        for (int j = i; j < n; j++) {
            st.insert(arr[j]);

            // If count of distinct elements > k, then
            // don't extend the subarray further
            if (st.size() > k)
                break;
            if (st.size() == k)
                res += 1;
        }
    }
    return res;
}

int main() {
    vector<int> arr = {1, 2, 2, 3};
    int k = 2;
    cout << exactlyK(arr, k);
}


